import { describe } from 'vitest'
import { expect } from 'vitest'
import { it } from 'vitest'
import { dialogItem } from '../__tests__/dialog-fixtures.js'
import { dialogSprite } from '../__tests__/dialog-fixtures.js'
import { type IndexedImage } from '../assets/png.js'
import { appendDialogLine } from './dialog-box.js'
import { confirmDialog } from './dialog-box.js'
import { drawDialogBox } from './dialog-box.js'
